// ═══════════════════════════════════════════════════════════════════════════
// ŒNO — Bibliothèque des vins
// 200 appellations françaises et internationales, pensées pour les néophytes.
// Chaque vin a : jauges de goût (1-5), difficulté, prix moyen, description simple.
// ═══════════════════════════════════════════════════════════════════════════

const TYPE_LABELS = { red: 'Rouge', white: 'Blanc', 'rosé': 'Rosé', sweet: 'Liquoreux', sparkling: 'Effervescent' }
const TYPE_COLORS = { red: '#8c2f39', white: '#c9a84c', 'rosé': '#e58f8f', sweet: '#b8860b', sparkling: '#5b8db8' }

// difficulte : 'facile' (à aimer direct) | 'explorer' (un cran plus loin) | 'pointu' (pour curieux avertis)
// jauges : puissance (léger→puissant), douceur (sec→doux), tanins (souple→costaud) — 1 à 5
function vin(o) {
  return {
    typeLabel: TYPE_LABELS[o.type],
    color: o.color || TYPE_COLORS[o.type],
    carafage: null,
    domaines: [],
    ...o,
  }
}

