// gardeForMillesime — calcule la fenêtre de garde d'un vin pour un millésime donné.
// Cherche dans MILLESIMES_DB (année + région + type) le "gardeMax" (colonne 5),
// sinon retombe sur wine.drinkUntil. Retourne { from, until } en années civiles.
export function gardeForMillesime(wine, year) {
  const y = Number(year)
  if (!wine || !y) return null
  // Vins grand public : à boire jeunes. On ne va PAS emprunter la garde d'un
  // grand terroir de la même région — on garde leur propre fenêtre courte.
  if (wine.grandPublic) return { from: y + wine.drinkFrom, until: y + wine.drinkUntil }
  const typeLabel = TYPE_LABELS[wine.type]
  const match = MILLESIMES_DB.find(row => {
    const [rowYear, rowType, rowRegion, rowAppellation] = row
    if (rowYear !== y) return false
    if (rowRegion !== wine.region) return false
    if (rowType && typeLabel && rowType !== typeLabel) return false
    // Match par appellation si possible, sinon on accepte juste année+région+type
    if (rowAppellation && wine.appellation && rowAppellation !== wine.appellation) {
      return false
    }
    return true
  }) || MILLESIMES_DB.find(row => {
    const [rowYear, rowType, rowRegion] = row
    return rowYear === y && rowRegion === wine.region && (!rowType || !typeLabel || rowType === typeLabel)
  })
  const gardeMax = match ? match[5] : wine.drinkUntil
  return {
    from: y + wine.drinkFrom,
    until: y + gardeMax,
  }
}

// ═══ Dérivés ═════════════════════════════════════════════════════════════
export const WINE_DB_BY_REGION = WINE_DB.reduce((acc, wine) => {
  if (!acc[wine.region]) acc[wine.region] = []
  acc[wine.region].push(wine)
  return acc
}, {})

export const WINE_DB_APPELLATIONS = WINE_DB.map(w => ({
  appellation: w.appellation,
  region:      w.region,
  type:        w.type,
  cepages:     w.cepages,
  serviceTemp: w.serviceTemp,
  carafage:    w.carafage,
  drinkFrom:   w.drinkFrom,
  drinkUntil:  w.drinkUntil,
  accords:     w.accords,
  aromes:      w.aromes,
}))

export const REGIONS_LIST = [...new Set(WINE_DB.map(w => w.region))]

// Repères grand public (supermarché) vs vins de terroir (appellations).
// La carte des vignobles et le décompte « appellations » n'utilisent que le terroir.
export const WINE_DB_GRAND_PUBLIC = WINE_DB.filter(w => w.grandPublic)
export const WINE_DB_TERROIR = WINE_DB.filter(w => !w.grandPublic)

// WINE_DB_DOMAINES — annuaire dédupliqué de tous les domaines cités dans WINE_DB,
// avec les vins/appellations/régions dans lesquels chacun apparaît.
export const WINE_DB_DOMAINES = (() => {
  const map = new Map()
  for (const w of WINE_DB) {
    for (const d of w.domaines) {
      if (!map.has(d.name)) {
        map.set(d.name, {
          name: d.name,
          notes: [],
          wines: [],
          regions: new Set(),
          appellations: new Set(),
          confidentiel: false,
          histoire: null,
          url: null,
        })
      }
      const entry = map.get(d.name)
      entry.notes.push(d.note)
      entry.wines.push({ id: w.id, appellation: w.appellation, region: w.region, type: w.type, color: w.color })
      entry.regions.add(w.region)
      entry.appellations.add(w.appellation)
      if (d.confidentiel) entry.confidentiel = true
      if (d.histoire && !entry.histoire) entry.histoire = d.histoire
      if (d.url && !entry.url) entry.url = d.url
    }
  }
  return [...map.values()]
    .map(e => ({ ...e, regions: [...e.regions], appellations: [...e.appellations] }))
    .sort((a, b) => a.name.localeCompare(b.name, 'fr'))
})()

// CONFIDENTIEL_DOMAINES — les petits domaines mis en avant (badge "Petit domaine",
// section "Domaine du moment" sur la landing page).
export const CONFIDENTIEL_DOMAINES = WINE_DB_DOMAINES.filter(d => d.confidentiel)

export const DIFFICULTE_CONFIG = {
  facile:   { label: 'Facile à aimer', color: '#4d7c50', bg: '#e8f0e8' },
  explorer: { label: 'Pour explorer', color: '#b8722c', bg: '#f7ecd9' },
  pointu:   { label: 'Pointu',         color: '#8c2f39', bg: '#f5e3e5' },
}

// ── Variantes de couleur d'une même appellation ──────────────────────────────
// « Sancerre », « Sancerre Rouge » et « Sancerre Rosé » partagent la même base.
export const baseAppellation = (a = '') =>
  a.replace(/\s+(Rouge|Blanc|Rosé|Clairet|Sec)$/i, '')

export function variantesDe(wine) {
  if (!wine?.appellation) return []
  const base = baseAppellation(wine.appellation)
  return WINE_DB.filter(w => w.id !== wine.id && baseAppellation(w.appellation) === base)
}

// ── Vins similaires — « introuvable en rayon ? essayez plutôt… » ─────────────
// Même couleur obligatoire, puis proximité : cépage partagé, même région,
// profil de goût (jauges) et prix comparables. Sert de plan B en magasin
// quand l'appellation cherchée n'est pas en stock.
export function vinsSimilaires(wine, n = 3) {
  if (!wine) return []
  const base = baseAppellation(wine.appellation || '')
  const cepages = new Set((wine.cepages || []).map(c => c.toLowerCase()))
  return WINE_DB
    .filter(w => w.id !== wine.id && w.type === wine.type && baseAppellation(w.appellation) !== base)
    .map(w => {
      let s = 0
      if (w.cepages?.some(c => cepages.has(c.toLowerCase()))) s += 4
      if (w.region === wine.region) s += 2
      if (wine.jauges && w.jauges) {
        s += 3 - (Math.abs(w.jauges.puissance - wine.jauges.puissance)
                + Math.abs(w.jauges.douceur - wine.jauges.douceur)
                + Math.abs(w.jauges.tanins - wine.jauges.tanins)) / 2
      }
      const prixRef = wine.prixMoyen || 15
      s -= Math.min(3, Math.abs((w.prixMoyen || 15) - prixRef) / prixRef * 3)
      return { w, s }
    })
    .sort((a, b) => b.s - a.s)
    .slice(0, n)
    .map(x => x.w)
}
